# Rebuilds lib/lucide_icons.dart from an upstream lucide_icons_flutter checkout, keeping only the
# plain `Lucide` family. Upstream also ships six weighted fonts (Lucide100..600, ~2.9 MB) that the
# icon tree shaker can't drop because nothing references them.
#
#   python3 tool/strip.py ~/.pub-cache/hosted/pub.dev/lucide_icons_flutter-<version>
#   cp ~/.pub-cache/hosted/pub.dev/lucide_icons_flutter-<version>/assets/lucide.ttf assets/
import pathlib
import re
import sys

src = pathlib.Path(sys.argv[1]) / 'lib' / 'lucide_icons.dart'
out = pathlib.Path(__file__).resolve().parent.parent / 'lib' / 'lucide_icons.dart'
entry = re.compile(
    r"static const IconData (\w+) = const IconData\((\d+),\s*fontFamily: '(\w+)',\s*"
    r"fontPackage: 'lucide_icons_flutter'(,\s*matchTextDirection: true)?\);"
)
lines = []
for name, code, family, dir_ in entry.findall(src.read_text()):
    if family != 'Lucide':
        continue
    rtl = ', matchTextDirection: true' if dir_ else ''
    lines.append(
        f"  static const IconData {name} = IconData({code}, fontFamily: 'Lucide', "
        f"fontPackage: 'lucide_icons_flutter'{rtl});"
    )
out.write_text(
    '// Generated by tool/strip.py from upstream lucide_icons_flutter: the `Lucide` family only.\n'
    '// ignore_for_file: constant_identifier_names\n'
    "library;\n\nimport 'package:flutter/widgets.dart';\n\n"
    '@staticIconProvider\nclass LucideIcons {\n  const LucideIcons._();\n\n' + '\n'.join(lines) + '\n}\n'
)
print(f'{len(lines)} icons -> {out}')
